    const mean = (arr) => arr.length ? arr.reduce((a, b) => a + b, 0) / arr.length : 0;
    const median = (arr) => {
      if (!arr.length) return 0;
      const s = [...arr].sort((a, b) => a - b);
      const mid = Math.floor(s.length / 2);
      return s.length % 2 !== 0 ? s[mid] : (s[mid - 1] + s[mid]) / 2;
    };
    const stdDev = (arr) => {
      if (arr.length <= 1) return 0;
      const m = mean(arr);
      return Math.sqrt(arr.reduce((acc, v) => acc + Math.pow(v - m, 2), 0) / (arr.length - 1));
    };

    async function syncWithBackendApi() {
      let apiResponded = false;
      try {
        const res = await TobaKostApi.analytics();
        apiResponded = true;
        if (!res.ok) {
          let detail = '';
          try {
            const body = await res.json();
            detail = body.message ? `: ${body.message}` : '';
          } catch (parseError) {
            console.warn('Respons error API tidak berisi JSON.', parseError);
          }
          const error = new Error(`API merespons HTTP ${res.status}${detail}`);
          error.httpStatus = res.status;
          throw error;
        }
        const fresh = await res.json();
        if (!fresh || !Array.isArray(fresh.records)) throw new Error('Respons API tidak berisi daftar records yang valid.');
        APP_PAYLOAD = fresh;
        ALL_RECORDS = fresh.records;
        const bestAlgorithm = fresh.best_algorithm || Object.entries(fresh.metrics || {})
          .sort((a, b) => a[1].MAE - b[1].MAE)[0]?.[0];
        if (bestAlgorithm) {
          const selector = document.getElementById('predAlgo');
          Array.from(selector.options).forEach(option => {
            option.textContent = option.value === bestAlgorithm
              ? `${option.value} · Terbaik berdasarkan MAE`
              : option.value;
          });
          selector.value = bestAlgorithm;
        }
        setDataSourceStatus(`SQLite API · ${ALL_RECORDS.length} sampel`, `SQLite Data Warehouse · ${ALL_RECORDS.length} sampel`, 'API berhasil dimuat dari SQLite Data Warehouse.', 'online');
        applyGlobalFilter();
        await runPredictionCalculator();
      } catch (e) {
        const count = ALL_RECORDS.length;
        if (apiResponded) {
          setDataSourceStatus('API error · snapshot lokal', `Snapshot HTML · ${count} sampel · API merespons`, e.message, 'error');
          console.error('API dapat dijangkau tetapi gagal memuat data terbaru.', e);
        } else {
          setDataSourceStatus('API offline · snapshot lokal', `Snapshot HTML · ${count} sampel · API offline`, e.message, 'offline');
          console.warn('API tidak dapat dijangkau; menampilkan snapshot HTML yang tertanam.', e);
        }
      }
    }

    function setDataSourceStatus(label, sourceLabel, detail, status) {
      const badge = document.getElementById('apiBadge');
      const source = document.getElementById('dataSourceText');
      badge.textContent = label;
      badge.title = detail;
      badge.className = status === 'online'
        ? 'mt-3 inline-flex max-w-full items-center rounded-full px-2.5 py-1 text-[10px] font-semibold bg-emerald-50 text-emerald-700 border border-emerald-100'
        : status === 'error'
          ? 'mt-3 inline-flex max-w-full items-center rounded-full px-2.5 py-1 text-[10px] font-semibold bg-rose-50 text-rose-700 border border-rose-100'
          : 'mt-3 inline-flex max-w-full items-center rounded-full px-2.5 py-1 text-[10px] font-semibold bg-amber-50 text-amber-800 border border-amber-200';
      source.textContent = sourceLabel;
      source.title = detail;
    }

    function switchTab(tabId, btnEl) {
      document.querySelectorAll('.tab-section').forEach(s => s.classList.add('hidden'));
      const target = document.getElementById(tabId);
      if (!target) return;
      target.classList.remove('hidden');
      document.querySelectorAll('.sidebar-btn').forEach(b => b.classList.remove('active'));
      if (btnEl) btnEl.classList.add('active');
      closeMobileSidebar();

      setTimeout(() => {
        target.querySelectorAll('.js-plotly-plot').forEach(el => Plotly.Plots.resize(el));
        if (tabId === 'tab4') initOrUpdateMap();
      }, 60);
    }

    const SECTION_TABS = {
      overview: ['tab1', 'tab2'],
      location: ['tab3', 'tab4'],
      discovery: ['tab5', 'tab6'],
      'machine-learning': ['tab7', 'tab8', 'tab9'],
      'data-admin': ['tab10']
    };

    function switchSection(sectionId, btnEl) {
      const tabIds = SECTION_TABS[sectionId] || SECTION_TABS.overview;
      document.querySelectorAll('.tab-section').forEach(section => section.classList.add('hidden'));
      tabIds.forEach(tabId => {
        const section = document.getElementById(tabId);
        if (section) section.classList.remove('hidden');
      });
      document.querySelectorAll('.sidebar-btn').forEach(button => button.classList.remove('active'));
      if (btnEl) btnEl.classList.add('active');
      closeMobileSidebar();
      setTimeout(() => {
        tabIds.forEach(tabId => {
          const target = document.getElementById(tabId);
          if (!target) return;
          target.querySelectorAll('.js-plotly-plot').forEach(el => Plotly.Plots.resize(el));
        });
        if (tabIds.includes('tab4')) initOrUpdateMap();
      }, 60);
    }

    async function loadCapabilities() {
      try {
        const res = await TobaKostApi.capabilities();
        const capabilities = await res.json();
        const roleBadge = document.getElementById('roleBadge');
        if (roleBadge) roleBadge.textContent = `Role: ${capabilities.role}`;
        const adminPanel = document.getElementById('adminWritePanel');
        if (adminPanel) adminPanel.classList.toggle('hidden', capabilities.role !== 'admin');
      } catch (error) {
        console.warn('Capability API tidak tersedia; menggunakan role user.', error);
      }
    }

