    async function loadDwTablePreview() {
      const tbl = document.getElementById('selectDwTable').value;
      let cols = [], rows = [];

      try {
        const res = await TobaKostApi.warehouse(tbl);
        if (res.ok) {
          const data = await res.json();
          cols = data.columns;
          rows = data.rows;
        }
      } catch (e) {}

      if (!cols.length && APP_PAYLOAD.star_schema && APP_PAYLOAD.star_schema[tbl]) {
        cols = APP_PAYLOAD.star_schema[tbl].columns;
        rows = APP_PAYLOAD.star_schema[tbl].rows;
      }

      document.querySelector('#tableDwPreview thead').innerHTML = `<tr>${cols.map(c => `<th>${c}</th>`).join('')}</tr>`;
      document.querySelector('#tableDwPreview tbody').innerHTML = rows.map(r =>
        `<tr>${cols.map(c => `<td>${r[c] !== null && r[c] !== undefined ? r[c] : ''}</td>`).join('')}</tr>`
      ).join('');
      refreshTableControls();
    }

    async function submitNewKosToDatabase() {
      const body = {
        nama_kost: document.getElementById('newNamaKos').value || 'Kost Baru Toba',
        kecamatan: document.getElementById('newKecamatan').value,
        desa_kelurahan: document.getElementById('newDesa').value || 'Sitoluama',
        harga_bulanan_norm: Number(document.getElementById('newHarga').value || 750000),
        jarak_ke_kampus_kantor_sekolah_terdekat_km: Number(document.getElementById('newJarakKampus').value || 0.7),
        km_dalam: document.getElementById('newKmDalam').checked ? 1 : 0,
        is_wifi: document.getElementById('newWifi').checked ? 1 : 0,
        is_ac: document.getElementById('newAc').checked ? 1 : 0
      };

      const msgEl = document.getElementById('insertMsg');
      try {
        const res = await TobaKostApi.createKos(body);
        if (res.ok) {
          const out = await res.json();
          msgEl.textContent = out.message;
          await syncWithBackendApi();
          return;
        }
      } catch (e) {}
      msgEl.textContent = 'Pastikan server.py sedang berjalan (python server.py) untuk menyimpan ke SQLite.';
    }

    function exportFilteredCsv() {
      if (!FILTERED_RECORDS.length) return;
      const cols = Object.keys(FILTERED_RECORDS[0]);
      const csvRows = [
        cols.join(','),
        ...FILTERED_RECORDS.map(r => cols.map(c => `"${String(r[c] ?? '').replace(/"/g, '""')}"`).join(','))
      ];
      const blob = new Blob([csvRows.join('\n')], { type: 'text/csv;charset=utf-8;' });
      const a = document.createElement('a');
      a.href = URL.createObjectURL(blob);
      a.download = 'tobakost_analytics_export.csv';
      a.click();
    }

    function setupTableControls() {
      document.querySelectorAll('table').forEach(table => {
        if (TABLE_STATES.has(table) || !table.tBodies.length) return;
        const state = { query: '', page: 1, pageSize: 10, sortColumn: -1, sortDirection: 1 };
        TABLE_STATES.set(table, state);

        const toolbar = document.createElement('div');
        toolbar.className = 'table-toolbar';
        const search = document.createElement('input');
        search.type = 'search';
        search.placeholder = 'Cari di tabel...';
        search.setAttribute('aria-label', 'Cari pada tabel');
        search.addEventListener('input', () => {
          state.query = search.value.trim().toLocaleLowerCase('id');
          state.page = 1;
          renderTablePage(table);
        });

        const pageSize = document.createElement('select');
        pageSize.setAttribute('aria-label', 'Jumlah baris per halaman');
        [10, 25, 50].forEach(size => {
          const option = document.createElement('option');
          option.value = String(size);
          option.textContent = `${size} baris`;
          pageSize.append(option);
        });
        pageSize.addEventListener('change', () => {
          state.pageSize = Number(pageSize.value);
          state.page = 1;
          renderTablePage(table);
        });
        const hint = document.createElement('span');
        hint.textContent = 'Klik judul kolom untuk mengurutkan';
        toolbar.append(search, pageSize, hint);

        const pager = document.createElement('div');
        pager.className = 'table-pager';
        const summary = document.createElement('span');
        const actions = document.createElement('div');
        actions.className = 'flex items-center gap-2';
        const previous = document.createElement('button');
        previous.type = 'button';
        previous.textContent = 'Sebelumnya';
        previous.addEventListener('click', () => {
          state.page -= 1;
          renderTablePage(table);
        });
        const next = document.createElement('button');
        next.type = 'button';
        next.textContent = 'Berikutnya';
        next.addEventListener('click', () => {
          state.page += 1;
          renderTablePage(table);
        });
        actions.append(previous, next);
        pager.append(summary, actions);

        const scrollContainer = table.parentElement;
        const card = scrollContainer && scrollContainer.parentElement;
        if (!card) return;
        card.insertBefore(toolbar, scrollContainer);
        card.insertBefore(pager, scrollContainer.nextSibling);
        state.summary = summary;
        state.previous = previous;
        state.next = next;
        table.addEventListener('click', event => {
          const header = event.target.closest('th');
          if (!header || !table.tHead || !table.tHead.contains(header)) return;
          const column = Array.from(header.parentElement.cells).indexOf(header);
          if (state.sortColumn === column) state.sortDirection *= -1;
          else {
            state.sortColumn = column;
            state.sortDirection = 1;
          }
          state.page = 1;
          renderTablePage(table);
        });
        renderTablePage(table);
      });
    }

    function renderTablePage(table) {
      const state = TABLE_STATES.get(table);
      if (!state || !table.tBodies.length) return;
      const tbody = table.tBodies[0];
      const rows = Array.from(tbody.rows);
      if (state.sortColumn >= 0) {
        rows.sort((a, b) => {
          const left = a.cells[state.sortColumn]?.textContent.trim() || '';
          const right = b.cells[state.sortColumn]?.textContent.trim() || '';
          return left.localeCompare(right, 'id', { numeric: true, sensitivity: 'base' }) * state.sortDirection;
        });
        rows.forEach(row => tbody.append(row));
      }
      const matching = rows.filter(row => row.textContent.toLocaleLowerCase('id').includes(state.query));
      const pages = Math.max(1, Math.ceil(matching.length / state.pageSize));
      state.page = Math.min(Math.max(1, state.page), pages);
      const start = (state.page - 1) * state.pageSize;
      const visible = new Set(matching.slice(start, start + state.pageSize));
      rows.forEach(row => { row.hidden = !visible.has(row); });
      if (state.summary) state.summary.textContent = matching.length
        ? `Menampilkan ${start + 1}–${Math.min(start + state.pageSize, matching.length)} dari ${matching.length} baris`
        : 'Tidak ada baris yang cocok';
      if (state.previous) state.previous.disabled = state.page <= 1;
      if (state.next) state.next.disabled = state.page >= pages;
    }

    function refreshTableControls() {
      setupTableControls();
      document.querySelectorAll('table').forEach(table => {
        const state = TABLE_STATES.get(table);
        if (state) {
          state.page = 1;
          renderTablePage(table);
        }
      });
    }

    const TABLE_STATES = new WeakMap();

    window.addEventListener('DOMContentLoaded', () => {
      setDataSourceStatus('Snapshot HTML · memeriksa API', `Snapshot HTML · ${ALL_RECORDS.length} sampel`, 'Memeriksa API data. Snapshot tertanam ditampilkan sementara.', 'offline');
      try {
        if (localStorage.getItem('tobakost-sidebar-collapsed') === '1') document.body.classList.add('sidebar-collapsed');
      } catch (e) {
        console.warn('Preferensi sidebar tidak dapat dibaca.', e);
      }
      setupTableControls();
      applyGlobalFilter();
      runPredictionCalculator();
      syncWithBackendApi();
      loadCapabilities();
    });
